import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] arr = new long[(int) n];
        for (int i = 0; i < arr.length; i++) arr[i] = Long.parseLong(next());

        int size = (int) n;
        Map<Long, List<Integer>> where = new HashMap<>();
        for (int i = 0; i < size; i++) where.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        int[] dist = new int[size];
        Arrays.fill(dist, -1);
        dist[0] = 0;
        List<Integer> queue = new ArrayList<>();
        queue.add(0);
        for (int q = 0; q < queue.size(); q++) {
            int i = queue.get(q);
            List<Integer> targets = new ArrayList<>();
            targets.add(i - 1);
            targets.add(i + 1);
            List<Integer> same = where.remove(arr[i]);
            if (same != null) targets.addAll(same);
            for (int j : targets) {
                if (j >= 0 && j < size && dist[j] < 0) {
                    dist[j] = dist[i] + 1;
                    queue.add(j);
                }
            }
        }
        System.out.println(dist[size - 1]);
    }
}
